   return {token:this._token(node), role:node.dataset.node, id:node.dataset.row,
           parent:parent ? parent.dataset.row : null, text:node.textContent,
           index:node.getAttribute('data-index'), first:node.getAttribute('data-first'),
           last:node.getAttribute('data-last'), connected:node.isConnected};
  });
  const removed = this._previous.filter(node => !elements.includes(node)).map(node =>
   ({token:this._token(node), role:node.dataset.node, id:node.dataset.row, connected:node.isConnected}));
  this._previous = elements;
  this.dispatchEvent(new CustomEvent('observe', {detail:{step:this._step, nodes, removed}}));
 }
}
